import csv
import requests
import time
headers = {
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:109.0) Gecko/20100101 Firefox/116.0",
    "Referer": "https://music.163.com/"
}
cookies = {
 'MUSIC_U':""
}
file = open('data/raw_data.csv','r',newline='',encoding='utf-8-sig')
reader = csv.DictReader(file)

fieldnames = ['id','comments_content','comments_likedCount']
f = open('data/comments.csv','w',newline='',encoding='utf-8-sig')
writer = csv.DictWriter(f,fieldnames=fieldnames)
writer.writeheader()

for song in reader:
    id = song['id']
    url = f"https://music.163.com/api/v1/resource/comments/R_SO_4_{id}"
    response = requests.get(url=url,headers=headers,cookies=cookies)
    data = response.json()
    for comment in data['hotComments'][:3]:
        row={'id':id,'comments_content':comment['content'],'comments_likedCount':comment['likedCount']}
        writer.writerow(row)
    # time.sleep(0.5)
file.close()
f.close()